INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1658, 'math', 2, 'advanced_math', 'nonlinear_equations', 'hard', '[See practice test 4 PDF — Math Module 2, Question 21]', NULL, '["51", "0", "1", "-1"]', 0, 'The correct answer is 51. A quadratic equation of the form ax^2 + bx + c = 0, where a, b, and c are constants, has no real solution if and only if its discriminant, b^2 - 4ac, is negative. In the given equation, a = -1 and c = -676. Substituting -1 for a and -676 for c in this expression yields a discriminant of b^2 - 4(-1)(-676), or b^2 - 2704. Setting this less than 0 gives b^2 < 2704, so |b| < 52. The greatest integer less than 52 is 51.', 'This is a College Board practice test question. Review the official explanation for detailed analysis.', 'Work through more practice test questions in this section to build familiarity with the test format.', 1, 150, '["student_produced_response", "figure_required"]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1659, 'math', 2, 'problem_solving', 'percentages', 'advanced', '210 is p % greater than 30. What is the value of p ?', NULL, '["600", "0", "1", "-1"]', 0, 'The correct answer is 600. It''s given that 210 is % p greater than 30. It follows that ( )( ) 100 210 1 30 p = + . Dividing both sides of this equation by 30 yields 100 7 1 p = + . Subtracting 1 from both sides of this equation yields 100 6 p = . Multiplying both sides of this equation by 100 yields 600 p = . Therefore, the value of p is 600. n', 'This is a College Board practice test question. Review the official explanation for detailed analysis.', 'Work through more practice test questions in this section to build familiarity with the test format.', 1, 150, '["student_produced_response"]');
